#!/usr/bin/env python3
"""Regenerate the Contributors section of README.md from the GitHub API.

Usage: GH_TOKEN=... python update-contributors.py <owner/repo> [README.md]
Writes the avatar grid between the CONTRIBUTORS:START / CONTRIBUTORS:END markers,
appending a new "## Contributors" section if the markers are missing.
"""
import json
import os
import re
import sys
import urllib.request

START = "<!-- CONTRIBUTORS:START - generated by .github/scripts/update-contributors.py, do not edit by hand -->"
END = "<!-- CONTRIBUTORS:END -->"
SIZE = 64


def fetch_contributors(repo, token):
    people, page = [], 1
    while True:
        req = urllib.request.Request(
            f"https://api.github.com/repos/{repo}/contributors?per_page=100&page={page}",
            headers={
                "Accept": "application/vnd.github+json",
                "Authorization": f"Bearer {token}",
                "User-Agent": "contributors-readme-updater",
            },
        )
        with urllib.request.urlopen(req) as resp:
            batch = json.load(resp)
        if not batch:
            return people
        people += [c for c in batch if c.get("type") == "User" and not c["login"].endswith("[bot]")]
        page += 1


def render(people):
    links = [
        f'<a href="{p["html_url"]}" title="{p["login"]}">'
        f'<img src="https://avatars.githubusercontent.com/u/{p["id"]}?v=4&s={SIZE * 2}" '
        f'width="{SIZE}" height="{SIZE}" alt="{p["login"]}"/></a>'
        for p in people
    ]
    return START + "\n<p>\n" + "\n".join(links) + "\n</p>\n" + END


def main():
    repo = sys.argv[1]
    path = sys.argv[2] if len(sys.argv) > 2 else "README.md"
    token = os.environ.get("GH_TOKEN") or os.environ["GITHUB_TOKEN"]
    block = render(fetch_contributors(repo, token))

    with open(path, encoding="utf-8") as f:
        text = f.read()
    pattern = re.compile(re.escape(START.split(" - ")[0]) + r".*?" + re.escape(END), re.S)
    if pattern.search(text):
        new = pattern.sub(lambda _: block, text, count=1)
    else:
        new = text.rstrip() + "\n\n---\n\n## Contributors\n\n" + block + "\n"
    if new != text:
        with open(path, "w", encoding="utf-8", newline="\n") as f:
            f.write(new)
        print("README updated")
    else:
        print("README already up to date")


if __name__ == "__main__":
    main()
